// 故意保留接线缺陷；Explore 只修复隔离副本。
export function produceCompletion() {
  return { deliveryId: 'd01', changeId: 'second-entry', kind: 'change-archived' };
}
export function consumeCompletion(message: { deliveryId: string; changeId: string; kind: string }) {
  if (message.kind !== 'change-archived') throw new Error('expected archived completion');
  return `${message.deliveryId}:${message.changeId}`;
}
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import { produceCompletion } from './producer.ts';
import { consumeCompletion } from './consumer.ts';

test('producer and consumer share the archived completion contract', () => {
  fs.appendFileSync('executed-groups.jsonl', JSON.stringify({ group: 'integration' }) + '\n');
  assert.equal(consumeCompletion(produceCompletion()), 'd01:second-entry');
});
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import { consumeCompletion } from './consumer.ts';

test('consumer accepts archived completion and rejects a wrong contract', () => {
  fs.appendFileSync('executed-groups.jsonl', JSON.stringify({ group: 'unit' }) + '\n');
  assert.equal(consumeCompletion({ deliveryId: 'd01', changeId: 'first-entry', kind: 'change-archived' }), 'd01:first-entry');
  assert.throws(() => consumeCompletion({ deliveryId: 'd01', changeId: 'first-entry', kind: 'wrong' }), /expected archived completion/);
});
